with src as (select * from subscriptions where plan not in ('premium', 'basic', 'enterprise') and plan = 'standard' and monthly_fee between 150 and 160), subscriptions_stats as (select plan, count(distinct monthly_fee) as unique_plans, sum(case when plan = 'enterprise' then monthly_fee else 0 end) as enterprise_monthly_fee from src group by plan) select plan, unique_plans, enterprise_monthly_fee from subscriptions_stats where enterprise_monthly_fee >= 46 order by plan, enterprise_monthly_fee desc;
